#!/usr/bin/env python3
"""Replace the Photo Studio gallery placeholder with persistent render storage."""

from pathlib import Path

APP = Path(__file__).resolve().parents[2]
PHOTO = APP / 'lib' / 'screens' / 'photo_studio_screen.dart'


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        if new in text:
            return text
        raise RuntimeError(f'could not locate {label}')
    if text.count(old) != 1:
        raise RuntimeError(f'expected one {label}, found {text.count(old)}')
    return text.replace(old, new, 1)


def main() -> None:
    text = PHOTO.read_text(encoding='utf-8')

    text = replace_once(
        text,
        """  bool _rendering = false;\n\n  @override\n""",
        """  bool _rendering = false;\n  int _renderCount = 0;\n\n  @override\n""",
        'render count state',
    )

    text = replace_once(
        text,
        """    _pan = widget.pan;\n  }\n\n  void _onScaleStart""",
        """    _pan = widget.pan;\n    WidgetsBinding.instance.addPostFrameCallback((_) => _refreshRenderCount());\n  }\n\n  String get _safeFloorId => widget.floor.id.replaceAll(\n    RegExp(r'[^A-Za-z0-9_-]'),\n    '_',\n  );\n\n  Future<Directory> _renderDirectory() async {\n    final root = await getApplicationDocumentsDirectory();\n    final directory = Directory('${root.path}/photo_renders/$_safeFloorId');\n    await directory.create(recursive: true);\n    return directory;\n  }\n\n  Future<List<File>> _renderFiles() async {\n    final directory = await _renderDirectory();\n    final files = <File>[];\n    await for (final entity in directory.list(followLinks: false)) {\n      if (entity is File && entity.path.toLowerCase().endsWith('.png')) {\n        files.add(entity);\n      }\n    }\n    files.sort((a, b) => b.statSync().modified.compareTo(a.statSync().modified));\n    return files;\n  }\n\n  Future<void> _refreshRenderCount() async {\n    try {\n      final files = await _renderFiles();\n      if (mounted) setState(() => _renderCount = files.length);\n    } catch (_) {\n      if (mounted) setState(() => _renderCount = 0);\n    }\n  }\n\n  Future<void> _showRenderGallery() async {\n    var files = await _renderFiles();\n    if (!mounted) return;\n    await showDialog<void>(\n      context: context,\n      builder: (dialogContext) => Dialog.fullscreen(\n        backgroundColor: ZamerColors.background,\n        child: SafeArea(\n          child: StatefulBuilder(\n            builder: (context, setGallery) => Column(\n              children: [\n                Container(\n                  height: 58,\n                  padding: const EdgeInsets.symmetric(horizontal: ZamerSpace.sm),\n                  decoration: const BoxDecoration(\n                    border: Border(\n                      bottom: BorderSide(color: ZamerColors.outlineSoft),\n                    ),\n                  ),\n                  child: Row(\n                    children: [\n                      IconButton(\n                        tooltip: 'Закрыть',\n                        onPressed: () => Navigator.pop(dialogContext),\n                        icon: const Icon(Icons.close_rounded),\n                      ),\n                      Expanded(\n                        child: Column(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          children: [\n                            const Text(\n                              'Галерея рендеров',\n                              style: TextStyle(\n                                color: ZamerColors.textPrimary,\n                                fontSize: 16,\n                                fontWeight: FontWeight.w900,\n                              ),\n                            ),\n                            Text(\n                              '${files.length} ${files.length == 1 ? 'кадр' : 'кадров'}',\n                              style: ZamerTypography.caption,\n                            ),\n                          ],\n                        ),\n                      ),\n                      const SizedBox(width: 44),\n                    ],\n                  ),\n                ),\n                Expanded(\n                  child: files.isEmpty\n                      ? const ZEmptyState(\n                          icon: Icons.photo_library_outlined,\n                          title: 'Рендеров пока нет',\n                          subtitle: 'Созданные кадры появятся здесь и сохранятся после перезапуска приложения.',\n                        )\n                      : GridView.builder(\n                          padding: const EdgeInsets.all(ZamerSpace.sm),\n                          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n                            crossAxisCount: 2,\n                            crossAxisSpacing: ZamerSpace.sm,\n                            mainAxisSpacing: ZamerSpace.sm,\n                            childAspectRatio: .78,\n                          ),\n                          itemCount: files.length,\n                          itemBuilder: (context, index) {\n                            final file = files[index];\n                            return Material(\n                              color: ZamerColors.surfaceLow,\n                              borderRadius: BorderRadius.circular(ZamerRadius.md),\n                              clipBehavior: Clip.antiAlias,\n                              child: InkWell(\n                                onTap: () => _openGalleryRender(file),\n                                child: Stack(\n                                  fit: StackFit.expand,\n                                  children: [\n                                    Image.file(\n                                      file,\n                                      fit: BoxFit.cover,\n                                      errorBuilder: (_, __, ___) => const Center(\n                                        child: Icon(Icons.broken_image_outlined),\n                                      ),\n                                    ),\n                                    Positioned(\n                                      left: 6,\n                                      right: 6,\n                                      bottom: 6,\n                                      child: Container(\n                                        padding: const EdgeInsets.symmetric(\n                                          horizontal: 7,\n                                          vertical: 5,\n                                        ),\n                                        decoration: BoxDecoration(\n                                          color: ZamerColors.background.withValues(alpha: .88),\n                                          borderRadius: BorderRadius.circular(ZamerRadius.sm),\n                                        ),\n                                        child: Row(\n                                          children: [\n                                            Expanded(\n                                              child: Text(\n                                                _renderFileLabel(file),\n                                                maxLines: 1,\n                                                overflow: TextOverflow.ellipsis,\n                                                style: const TextStyle(\n                                                  color: ZamerColors.textPrimary,\n                                                  fontSize: 9.5,\n                                                  fontWeight: FontWeight.w800,\n                                                ),\n                                              ),\n                                            ),\n                                            InkWell(\n                                              onTap: () async {\n                                                await file.delete();\n                                                files = await _renderFiles();\n                                                if (mounted) {\n                                                  setState(() => _renderCount = files.length);\n                                                }\n                                                setGallery(() {});\n                                              },\n                                              child: const Padding(\n                                                padding: EdgeInsets.all(3),\n                                                child: Icon(\n                                                  Icons.delete_outline_rounded,\n                                                  size: 17,\n                                                  color: ZamerColors.textMuted,\n                                                ),\n                                              ),\n                                            ),\n                                          ],\n                                        ),\n                                      ),\n                                    ),\n                                  ],\n                                ),\n                              ),\n                            );\n                          },\n                        ),\n                ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n    await _refreshRenderCount();\n  }\n\n  String _renderFileLabel(File file) {\n    final name = file.uri.pathSegments.last;\n    final parts = name.replaceFirst('.png', '').split('-');\n    if (parts.length >= 4) {\n      return '${parts[2]}×${parts[3]}';\n    }\n    return name;\n  }\n\n  Future<void> _openGalleryRender(File file) async {\n    if (!mounted) return;\n    await showDialog<void>(\n      context: context,\n      builder: (previewContext) => Dialog.fullscreen(\n        backgroundColor: ZamerColors.background,\n        child: SafeArea(\n          child: Column(\n            children: [\n              Container(\n                height: 58,\n                padding: const EdgeInsets.symmetric(horizontal: ZamerSpace.sm),\n                decoration: const BoxDecoration(\n                  border: Border(\n                    bottom: BorderSide(color: ZamerColors.outlineSoft),\n                  ),\n                ),\n                child: Row(\n                  children: [\n                    IconButton(\n                      tooltip: 'Назад',\n                      onPressed: () => Navigator.pop(previewContext),\n                      icon: const Icon(Icons.arrow_back_rounded),\n                    ),\n                    Expanded(\n                      child: Text(\n                        _renderFileLabel(file),\n                        textAlign: TextAlign.center,\n                        style: const TextStyle(\n                          color: ZamerColors.textPrimary,\n                          fontSize: 14,\n                          fontWeight: FontWeight.w900,\n                        ),\n                      ),\n                    ),\n                    IconButton(\n                      tooltip: 'Поделиться',\n                      onPressed: () => Share.shareXFiles([XFile(file.path)]),\n                      icon: const Icon(Icons.ios_share_outlined),\n                    ),\n                  ],\n                ),\n              ),\n              Expanded(\n                child: InteractiveViewer(\n                  minScale: .5,\n                  maxScale: 6,\n                  child: Center(child: Image.file(file, fit: BoxFit.contain)),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  void _onScaleStart""",
        'persistent render gallery helpers',
    )

    old_save = """      final dir = await getTemporaryDirectory();\n      final file = File(\n        '${dir.path}/zamer-photo-${DateTime.now().millisecondsSinceEpoch}-${size.$1}x${size.$2}.png',\n      );\n      await file.writeAsBytes(png, flush: true);\n"""
    new_save = """      final dir = await _renderDirectory();\n      final timestamp = DateTime.now().millisecondsSinceEpoch;\n      final file = File(\n        '${dir.path}/zamer-photo-$timestamp-${size.$1}-${size.$2}-${_time.name}.png',\n      );\n      await file.writeAsBytes(png, flush: true);\n      if (mounted) setState(() => _renderCount++);\n"""
    text = replace_once(text, old_save, new_save, 'persistent render save')

    old_gallery = """                  Expanded(\n                    child: _BottomAction(\n                      icon: Icons.photo_library_outlined,\n                      label: 'Галерея',\n                      value: 'Кадры',\n                      onTap: () => ScaffoldMessenger.of(context).showSnackBar(\n                        const SnackBar(\n                          content: Text(\n                            'Галерея проекта будет подключена отдельным проходом.',\n                          ),\n                        ),\n                      ),\n                    ),\n                  ),\n"""
    new_gallery = """                  Expanded(\n                    child: _BottomAction(\n                      icon: Icons.photo_library_outlined,\n                      label: 'Галерея',\n                      value: _renderCount == 0 ? 'Пусто' : '$_renderCount',\n                      onTap: _showRenderGallery,\n                    ),\n                  ),\n"""
    text = replace_once(text, old_gallery, new_gallery, 'gallery action')

    PHOTO.write_text(text, encoding='utf-8')
    print('Photo Studio now persists and browses rendered PNG files')


if __name__ == '__main__':
    main()
